/* Hidden attribute utility rule */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #141724;
  --color-card: #202538;
  --color-primary: #38bdf8;
  --color-primary-hover: #0284c7;
  --color-accent: #f59e0b;
  --color-danger: #f87171;
  --color-text-main: #f8fafc;
  --color-text-muted: #94a3b8;
  --color-border: #334155;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  /* Pixel pattern background generated via pure CSS */
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 20px 20px;
  color: var(--color-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
}

.game-container {
  width: 100%;
  max-width: 520px;
  background-color: var(--color-card);
  border: 3px solid var(--color-border);
  box-shadow: 6px 6px 0px 0px #0f111a;
  border-radius: 8px;
  padding: 2rem 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.game-header {
  text-align: center;
}

.title {
  font-size: 1.75rem;
  letter-spacing: -0.5px;
  color: var(--color-primary);
  margin-bottom: 0.25rem;
  text-transform: uppercase;
}

.subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
}

.stats-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.stat-box {
  background: rgba(0, 0, 0, 0.25);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  padding: 0.75rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.stat-label {
  font-size: 0.85rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  font-weight: 600;
}

.stat-value {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.stat-value.highlight {
  color: var(--color-accent);
}

.current-word-card {
  text-align: center;
  background: rgba(56, 189, 248, 0.08);
  border: 2px dashed var(--color-primary);
  border-radius: 6px;
  padding: 1.25rem 1rem;
}

.word-caption {
  display: block;
  font-size: 0.85rem;
  text-transform: uppercase;
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.active-word-display {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--color-text-main);
  word-break: break-all;
}

.word-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.input-label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-main);
}

.input-wrapper {
  display: flex;
  gap: 0.5rem;
}

input[type="text"] {
  flex: 1;
  min-width: 0;
  background-color: #111420;
  color: #fff;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  padding: 0.75rem 1rem;
  font-size: 1.1rem;
  outline: none;
  transition: border-color 0.15s ease;
}

input[type="text"]:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.3);
}

.btn {
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.25rem;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s;
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #0f172a;
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-primary:active {
  transform: translateY(2px);
}

.btn-secondary {
  background: transparent;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
}

.btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.05);
  color: var(--color-text-main);
}

.btn:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.message-box {
  font-size: 0.95rem;
  font-weight: 600;
  padding: 0.65rem 0.85rem;
  border-radius: 4px;
  border: 1px solid transparent;
}

.message-box.error {
  background-color: rgba(248, 113, 113, 0.15);
  border-color: var(--color-danger);
  color: var(--color-danger);
}

.message-box.success {
  background-color: rgba(56, 189, 248, 0.15);
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.chain-history-section {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-top: 1px solid var(--color-border);
  padding-top: 1rem;
}

.section-subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.chain-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  max-height: 140px;
  overflow-y: auto;
  padding: 0.25rem;
}

.chain-item {
  background-color: #171b29;
  border: 1px solid var(--color-border);
  color: var(--color-text-main);
  padding: 0.35rem 0.65rem;
  border-radius: 4px;
  font-size: 0.95rem;
}

.actions-row {
  display: flex;
  justify-content: flex-end;
}

@media (max-width: 440px) {
  .game-container {
    padding: 1.25rem 1rem;
  }

  .input-wrapper {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const INITIAL_WORD = "pixel";
  let chain = [INITIAL_WORD];
  let usedWords = new Set([INITIAL_WORD.toLowerCase()]);

  const wordForm = document.getElementById("word-form");
  const wordInput = document.getElementById("word-input");
  const chainCounter = document.getElementById("chain-counter");
  const targetLetterEl = document.getElementById("target-letter");
  const activeWordEl = document.getElementById("active-word");
  const chainList = document.getElementById("chain-list");
  const messageBox = document.getElementById("message-box");
  const resetBtn = document.getElementById("reset-btn");

  function getLastChar(word) {
    return word.charAt(word.length - 1).toLowerCase();
  }

  function updateUI() {
    const currentWord = chain[chain.length - 1];
    const nextExpectedLetter = getLastChar(currentWord);

    activeWordEl.textContent = currentWord;
    chainCounter.textContent = chain.length;
    targetLetterEl.textContent = nextExpectedLetter.toUpperCase();

    // Render history chain
    chainList.innerHTML = "";
    chain.forEach((word) => {
      const li = document.createElement("li");
      li.className = "chain-item";
      li.textContent = word;
      chainList.appendChild(li);
    });

    // Scroll history to bottom
    chainList.scrollTop = chainList.scrollHeight;
  }

  function showMessage(text, type = "error") {
    messageBox.textContent = text;
    messageBox.className = `message-box ${type}`;
    messageBox.removeAttribute("hidden");
  }

  function clearMessage() {
    messageBox.textContent = "";
    messageBox.className = "message-box";
    messageBox.setAttribute("hidden", "");
  }

  function handleWordSubmission(event) {
    event.preventDefault();
    clearMessage();

    const rawInput = wordInput.value.trim();
    const normalizedInput = rawInput.toLowerCase();

    if (!normalizedInput) {
      showMessage("Please enter a word.", "error");
      wordInput.focus();
      return;
    }

    // Validate alphabetical characters only
    if (!/^[a-zA-Z]+$/.test(rawInput)) {
      showMessage("Words may only contain letters.", "error");
      wordInput.focus();
      return;
    }

    // Check if word has already been used
    if (usedWords.has(normalizedInput)) {
      showMessage("Already used", "error");
      wordInput.select();
      return;
    }

    // Validate matching first letter with last letter of previous word
    const lastWord = chain[chain.length - 1];
    const expectedFirstLetter = getLastChar(lastWord);
    const actualFirstLetter = normalizedInput.charAt(0);

    if (actualFirstLetter !== expectedFirstLetter) {
      showMessage(
        `Word must begin with '${expectedFirstLetter.toUpperCase()}'.`,
        "error"
      );
      wordInput.select();
      return;
    }

    // Word is valid
    chain.push(normalizedInput);
    usedWords.add(normalizedInput);

    updateUI();
    wordInput.value = "";
    showMessage(`Added "${normalizedInput}"!`, "success");
    wordInput.focus();
  }

  function resetGame() {
    chain = [INITIAL_WORD];
    usedWords = new Set([INITIAL_WORD.toLowerCase()]);
    clearMessage();
    wordInput.value = "";
    updateUI();
    wordInput.focus();
  }

  // Attach DOM Event Listeners
  wordForm.addEventListener("submit", handleWordSubmission);
  resetBtn.addEventListener("click", resetGame);
  wordInput.addEventListener("input", () => {
    if (!messageBox.hasAttribute("hidden")) {
      clearMessage();
    }
  });

  // Initial render
  updateUI();
});
